IF OBJECT_ID('src.grady_diagnosis') IS NOT NULL
    DROP TABLE src.grady_diagnosis;
GO

CREATE TABLE src.grady_diagnosis (
    person_id BIGINT
    , diagnosis_key BIGINT
    , encounter_id BIGINT
    , diag_start_date DATE
    , diag_end_date DATE
    , diagnosis_code_type NVARCHAR(300)
    , diagnosis_code NVARCHAR(300)
    , diagnosis_desc NVARCHAR(850)
    , diagnosis_type NVARCHAR(350)
)
PRINT 'Table src.grady_diagnosis created.'
GO


INSERT INTO src.grady_diagnosis
SELECT
    DEF.PatientDurableKey AS person_id
    , DEF.DiagnosisKey AS diagnosis_key
    , DEF.EncounterKey AS encounter_id
    , STARTDT.DateValue AS diag_start_date
    , ENDDT.DateValue AS diag_end_date
    , DIM.Type AS diagnosis_code_type
    , DIM.value AS diagnosis_code
    , DIM.NameAndCode AS diagnosis_desc
    , DEF.type AS diagnosis_type
FROM src.grady_person P
INNER JOIN [CDW].[dbo].[DiagnosisEventFact] DEF ON P.DurableKey = DEF.PatientDurableKey
INNER JOIN [CDW].[dbo].[DiagnosisTerminologyDim] DIM ON DEF.DiagnosisKey = DIM.DiagnosisKey
INNER JOIN [CDW].[dbo].[DateDim] STARTDT ON DEF.StartDateKey = STARTDT.DateKey
INNER JOIN [CDW].[dbo].[DateDim] ENDDT ON DEF.EndDateKey = ENDDT.DateKey
WHERE (
    DIM.Value LIKE 'F%'
    OR DIM.Value LIKE 'Z5[5-9]%' OR DIM.[Value] LIKE 'Z6[0-5]%'
    OR DIM.Value IN ('G30', 'G30.0', 'G30.1', 'G30.8', 'G30.9', 'G31.83', 'G31.09') -- dementia related codes
)
AND DIM.Type LIKE '%ICD%10%'
ORDER BY STARTDT.DateValue DESC;
GO

ALTER TABLE src.grady_diagnosis
ADD Category VARCHAR(150)
GO

UPDATE src.grady_diagnosis
SET category = 'Social Determinants of Health'
WHERE
    diagnosis_code LIKE 'Z5[5-9]%' OR diagnosis_code LIKE 'Z6[0-5]%'

